example.snippet:
package main

import (
	"context"
	"dagger/my-module/internal/dagger"
)

type MyModule struct{}

func (m *MyModule) ShowSecret(
	ctx context.Context,
	token *dagger.Secret,
) (string, error) {
	return dag.Container().
		From("alpine:latest").
		WithSecretVariable("MY_SECRET", token).
		WithExec([]string{"sh", "-c", `echo this is the secret: $MY_SECRET`}).
		Stdout(ctx)
}

import dagger
from dagger import dag, function, object_type


@object_type
class MyModule:
    @function
    async def show_secret(
        self,
        token: dagger.Secret,
    ) -> str:
        return await (
            dag.container()
            .from_("alpine:latest")
            .with_secret_variable("MY_SECRET", token)
            .with_exec(
                [
                    "sh",
                    "-c",
                    ("echo this is the secret: $MY_SECRET"),
                ]
            )
            .stdout()
        )

import { dag, object, func, Secret } from "@dagger.io/dagger"

@object()
class MyModule {
  @func()
  async showSecret(token: Secret): Promise {
    return await dag
      .container()
      .from("alpine:latest")
      .withSecretVariable("MY_SECRET", token)
      .withExec(["sh", "-c", `echo this is the secret: $MY_SECRET`])
      .stdout()
  }
}
